class LifecycleTest {
    @BeforeAll  static void beforeAll()  { System.out.println("beforeAll"); }
    @BeforeEach void beforeEach()        { System.out.println("  beforeEach"); }
    @Test       void testOne()           { System.out.println("    testOne"); }
    @Test       void testTwo()           { System.out.println("    testTwo"); }
    @AfterEach  void afterEach()         { System.out.println("  afterEach"); }
    @AfterAll   static void afterAll()   { System.out.println("afterAll"); }
}
// beforeAll appears first and afterAll last. Each test name is surrounded
// by beforeEach and afterEach. testOne and testTwo may run in either order
// unless a method orderer is configured.
